CREATE TABLE worlds (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE records (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), kind TEXT NOT NULL CHECK(kind IN ('lore','entity','capture')), title TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL, tags TEXT NOT NULL, aliases TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('idea','draft','canon','hypothetical')), origin TEXT NOT NULL, canonical TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(id,world_id));
CREATE INDEX records_world ON records(world_id,kind);
CREATE TABLE revisions (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), record_id TEXT NOT NULL, version INTEGER NOT NULL, snapshot TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(record_id,world_id) REFERENCES records(id,world_id), UNIQUE(record_id,version));
CREATE TABLE links (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), source_id TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(source_id,world_id) REFERENCES records(id,world_id), FOREIGN KEY(target_id,world_id) REFERENCES records(id,world_id), UNIQUE(world_id,source_id,target_id));
CREATE TABLE relationships (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), source_id TEXT NOT NULL, target_id TEXT NOT NULL, label TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','canon')), origin TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(source_id,world_id) REFERENCES records(id,world_id), FOREIGN KEY(target_id,world_id) REFERENCES records(id,world_id), UNIQUE(world_id,source_id,target_id,label));
CREATE TABLE events (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), title TEXT NOT NULL, date_label TEXT NOT NULL, sort_order INTEGER, source_id TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'draft', origin TEXT NOT NULL DEFAULT 'user-authored', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(source_id,world_id) REFERENCES records(id,world_id));
CREATE TABLE proposals (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), payload TEXT NOT NULL, base_version INTEGER, before TEXT, evidence TEXT NOT NULL, reason TEXT NOT NULL, origin TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','accepted','rejected')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX proposals_world ON proposals(world_id,state);
CREATE VIRTUAL TABLE records_fts USING fts5(id UNINDEXED,world_id UNINDEXED,title,body,tags,aliases,category,tokenize='unicode61');
CREATE TRIGGER records_ai AFTER INSERT ON records BEGIN INSERT INTO records_fts(id,world_id,title,body,tags,aliases,category) VALUES(new.id,new.world_id,new.title,new.body,new.tags,new.aliases,new.category); END;
CREATE TRIGGER records_au AFTER UPDATE ON records BEGIN DELETE FROM records_fts WHERE id=old.id; INSERT INTO records_fts(id,world_id,title,body,tags,aliases,category) VALUES(new.id,new.world_id,new.title,new.body,new.tags,new.aliases,new.category); END;
CREATE TRIGGER records_ad AFTER DELETE ON records BEGIN DELETE FROM records_fts WHERE id=old.id; END;
